(function(){'use strict';
const data=JSON.parse(document.getElementById('page-data').textContent),pages=data.pages,assets=data.assets||{},files=data.files||{},mounts=data.mounts||[];
const article=document.getElementById('article'), nav=document.getElementById('nav'), search=document.getElementById('search'), results=document.getElementById('results');
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function normalize(s){let a=[];for(let p of s.split('/')){if(!p||p==='.')continue;if(p==='..'){if(!a.length)return null;a.pop()}else a.push(p)}return a.join('/')}
function resolve(current,href){if(/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(href))return null;let [p,frag]=href.split('#',2);try{p=decodeURIComponent(p.split('?')[0])}catch(e){}let mount=mounts.find(name=>current.startsWith(name+'/'));let base=href.startsWith('/')?(mount&&!p.startsWith('/'+mount+'/')?mount+'/':''):current.substring(0,current.lastIndexOf('/')+1);let key=p===''?current:normalize(base+p.replace(/^\//,''));return key===null?null:{key,frag:frag||''}}
function node(n){if(n.path)return '<li><a href="#/'+encodeURI(n.path)+'">'+esc(n.name)+'</a></li>';return '<li>'+esc(n.name)+'<ul>'+((n.children||[]).map(node).join(''))+'</ul></li>'}
nav.innerHTML='<ul>'+((data.nav.children||[]).map(node).join(''))+'</ul>';
function current(){let h=decodeURI(location.hash.replace(/^#\/?/,''));let [p,frag]=h.split('#',2);return {path:pages[p]?p:(pages['README.md']?'README.md':Object.keys(pages).sort()[0]),frag:frag||''}}
function render(){let {path,frag}=current();if(!path){article.textContent='No pages in this bundle';return}let md=pages[path];article.innerHTML=marked.parse(md);article.querySelectorAll('a[href],img[src]').forEach(el=>{let attr=el.tagName==='IMG'?'src':'href',href=el.getAttribute(attr),r=resolve(path,href);if(!r)return;if(assets[r.key]){el.setAttribute(attr,assets[r.key]);return}if(files[r.key]){el.setAttribute(attr,files[r.key]);return}if(pages[r.key]){el.setAttribute(attr,'#/'+encodeURI(r.key)+(r.frag?'#'+r.frag:''));return}if(!href.startsWith('#'))el.removeAttribute(attr)});article.querySelectorAll('pre code').forEach(el=>{if(el.className.includes('language-mermaid')){let div=document.createElement('div');div.className='mermaid';div.textContent=el.textContent;el.parentElement.replaceWith(div)}else if(window.hljs)hljs.highlightElement(el)});if(window.mermaid){mermaid.run({querySelector:'.mermaid'}).catch(e=>console.error(e))}if(frag)setTimeout(()=>document.getElementById(frag)?.scrollIntoView(),0);document.title=(path.split('/').pop()||data.title)+' — '+data.title}
function filter(){let q=search.value.trim().toLocaleLowerCase();results.innerHTML='';if(!q)return;let matches=Object.keys(pages).filter(p=>(p+' '+pages[p]).toLocaleLowerCase().includes(q)).slice(0,40);results.innerHTML='<p>'+matches.length+' result(s)</p><ul>'+matches.map(p=>'<li><a href="#/'+encodeURI(p)+'">'+esc(p)+'</a></li>').join('')+'</ul>'}
search.addEventListener('input',filter);window.addEventListener('hashchange',render);render();
})();
